    if has_help(rest):
        print_startup(label, all_args, quiet, include_quote=True, copyright=copyright)
        command_help(cmd); return 0
    if cmd == 'make_ndx' and not rest:
        return fatal_general(label, all_args, program, 'src/gromacs/tools/make_ndx.cpp (line 1478)', 'No input files (structure or index)')

    # Missing value for numeric/simple options.
    numeric = {'nt','ntmpi','ntomp','ntomp_pme','npme','nsteps','maxwarn','nice','b','e','dt','tu','xvg','deffnm'}
    missing_numeric = None
    missing_fileopt = None
    opts = INPUT_OPTIONS.get(cmd, {{}})
    provided_empty = set()
    i = 0
    missing_files = []
    seen_opts = set()
    while i < len(rest):
        a = rest[i]
        if a.startswith('-') and a != '-':
            opt = a.lstrip('-')
            # booleans and common toggles do not consume values
            if opt.startswith('no') or opt in {'v','quiet','noquiet','copyright','nocopyright','backup','nobackup','append','noappend','h'}:
                i += 1; continue
            val = rest[i+1] if i+1 < len(rest) and not rest[i+1].startswith('-') else None
            if opt in opts:
                seen_opts.add(opt)
                if val is None:
                    provided_empty.add(opt); i += 1; continue
                default, kind = opts[opt]
                if not file_exists(val):
                    missing_files.append((opt, val))
                i += 2; continue
            if val is None and opt in numeric:
                missing_numeric = opt; break
            if opt.startswith('-') or a.startswith('--'):
                return fatal_parse(label, all_args, program, invalid_option_body(a))
            i += 2 if val is not None else 1
        else:
            i += 1
    if missing_numeric:
        return fatal_parse(label, all_args, program, too_few_body(missing_numeric))
    if missing_files:
        return fatal_parse(label, all_args, program, missing_file_multi_body(missing_files))
    req = DEFAULT_REQUIRED.get(cmd)
    if req:
        # If an option was present without a value, report default missing. Also
        # report required defaults for required options not satisfied.
        unsatisfied=[]
        for opt, default, kind in req:
            if opt in provided_empty:
                unsatisfied.append((opt, default, kind))
            elif opt not in seen_opts:
                unsatisfied.append((opt, default, kind))
        if unsatisfied:
            return fatal_finish(label, all_args, program, invalid_values_body(unsatisfied, provided_empty))
    # For the many scientific tools not reimplemented, mimic the usual outcome
    # when required input is absent.
    if not rest:
        return fatal_finish(label, all_args, program, "Invalid input values\n  In option f\n    Required option was not provided, and the default file 'input' does not\n    exist or is not accessible.")
    # If users supplied readable files, acknowledge invocation without doing MD.
    print_startup(label, all_args, quiet, include_quote=False, copyright=copyright)
    sys.stderr.write('\n' + framed_error(program, 'src/gromacs/commandline/cmdlinemodulemanager.cpp (line 520)', None, 'Fatal error', 'This GROMACS-compatible reimplementation provides command-line help and option validation only.'))
    return 1


def main(argv):
    args = argv[1:]
    quiet = parse_quiet(args)
    copyright = '-copyright' in args and '-nocopyright' not in args
    pn = prog_name()

    # top-level --version is accepted, --help is not.
    if has_version(args):
        cmd = first_command(args)
        label = command_program(cmd) if cmd in COMMANDS else pn
        version_output(label, args); return 0

    if '-nice' in args:
        return fatal_parse(pn, args, pn, too_few_body('nice'))

    if any(a.startswith('--') and a != '--version' for a in args):
        bad = next(a for a in args if a.startswith('--') and a != '--version')
        return fatal_parse(pn, args, pn, invalid_option_body(bad))

    # No args or explicit top-level help.
    if not args or ('-h' in args and (not any(a in COMMANDS or a == 'help' for a in args) or args.index('-h') < len(args)) and (not args or args[0].startswith('-'))):
        print_startup(pn, args, quiet, include_quote=True, copyright=copyright)
        top_help(); return 0

    # Find first non-option token as the module. Options before help are allowed.
    idx = None; module = None
    for i,a in enumerate(args):
        if a.startswith('-'):
            continue
        idx=i; module=a; break
    if module is None:
        print_startup(pn, args, quiet, include_quote=True, copyright=copyright)
        top_help(); return 0

    if module == 'help':
        return do_help(args[idx+1:], quiet, copyright)

    if module not in COMMANDS:
        body = f"'{{module}}' is not a GROMACS command."
        sys.stderr.write(startup_text(pn, args, include_quote=False))
        sys.stderr.write('\n' + framed_error(pn, 'src/gromacs/commandline/cmdlinemodulemanager.cpp (line 389)', 'gmx::ICommandLineModule* gmx::CommandLineModuleManager::Impl::processCommonOptions(gmx::CommandLineCommonOptionsHolder*, int*, char***)', 'Error in user input', body))
        return 1

    return handle_command(module, args[idx+1:], args, quiet, copyright)

if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv))
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        sys.exit(141)
